use super::*;
fn e()->(EditorState,NodeId){let mut d=Document::default();d.sections[0].blocks=(vec![Block::Paragraph(Paragraph::plain("body"))]).into();let mut e=EditorState::new(d);let p=e.document.sections[0].blocks[0].clone();let Block::Paragraph(p)=p else{panic!()};e.set_caret(p.id,4);e.insert_footnote("rich αβ").unwrap();let id=e.document.review.footnotes.keys().next().unwrap().clone();e.enter_footnote(&id).unwrap();(e,id)}
#[test]fn note_typing_split_join_and_undo(){let(mut e,id)=e();let original=e.document.clone();e.insert_text("New ").unwrap();e.split_paragraph().unwrap();assert_eq!(e.document.review.footnotes[&id].blocks.len(),2);e.backspace().unwrap();assert_eq!(e.document.review.footnotes[&id].blocks.len(),1);assert!(e.undo());assert!(e.undo());assert!(e.undo());assert_eq!(e.document,original);}
